local({
  y <- as.numeric(format(datint, "%Y"))
  case_when(.wave == "2.5" ~ 2007, .wave == "3.5" ~ 2009, !is.na(y) ~ y, .default = as.numeric(modal_within(y, .wave)))
})

local({
  x <- coalesce(as.numeric(sep2), as.numeric(sep))
  lo <- stats::ave(x, .wave, FUN = function(v) stats::quantile(v, 0.4, na.rm = TRUE, names = FALSE))
  hi <- stats::ave(x, .wave, FUN = function(v) stats::quantile(v, 0.6, na.rm = TRUE, names = FALSE))
  case_when(is.na(x) ~ "Unknown", x <= lo ~ "Low", x > hi ~ "High", .default = "Medium")
})

local({
  items <- cbind(as.numeric(pa11a1), as.numeric(pa11a2), as.numeric(pa11a3), as.numeric(pa11a4), as.numeric(pa11a5))
  answered <- rowSums(!is.na(items) & items >= 1 & items <= 5)
  if_else(as.numeric(acons) >= 1 & answered >= 3, 6 - as.numeric(acons), NA_real_)
})

local({
  x <- coalesce(as.numeric(aparmon), as.numeric(aparmonb))
  if_else(x >= 1, 6 - x, NA_real_)
})

local({
  m <- coalesce(as.numeric(he21i), as.numeric(he19i))
  if_else(m >= 0, m / 60, NA_real_)
})

local({
  s <- coalesce(as.numeric(pc37a2), as.numeric(pc37a1))
  recode_values(s, 1 ~ "Public", c(2, 3) ~ "Private", default = "Unknown")
})

local({
  w <- as.numeric(wave)
  wy <- if_else(w %in% 1:8, 2002 + 2 * w, NA_real_)
  coalesce(
    if_else(as.numeric(y3test) == wy & as.numeric(y3write) > 0, as.numeric(y3write), NA_real_),
    if_else(as.numeric(y5test) == wy & as.numeric(y5write) > 0, as.numeric(y5write), NA_real_),
    if_else(as.numeric(y7test) == wy & as.numeric(y7write) > 0, as.numeric(y7write), NA_real_),
    if_else(as.numeric(y9test) == wy & as.numeric(y9write) > 0, as.numeric(y9write), NA_real_)
  )
})

