local({
  m <- cbind(as.numeric(se20a1))
  m[m < 0] <- NA
  n <- rowSums(!is.na(m))
  case_when(n == 0 ~ NA_character_, rowSums(m > 0, na.rm = TRUE) > 0 ~ "TRUE", .default = "FALSE")
})

